# Robust pagination and idempotent unfollow
def collect_all(api_func, token):
    items = []
    page = 0
    while True:
        batch = api_func(access_token=token, page_index=page)
        if not batch:
            break
        items.extend(batch)
        page += 1
    return items

liked_songs = collect_all(apis.spotify.show_liked_songs, token)
liked_artist_ids = set()
for song in liked_songs:
    for artist in song.artists:
        liked_artist_ids.add(artist.id)

current_following = collect_all(apis.spotify.show_following_artists, token)
for artist in current_following:
    if artist.artist_id not in liked_artist_ids:
        try:
            apis.spotify.unfollow_artist(access_token=token, artist_id=artist.artist_id)
        except Exception:
            apis.supervisor.complete_task(status="failure")
            raise
